<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
function arg(array $argv,string $key): string {foreach($argv as $a)if(str_starts_with($a,$key.'='))return substr($a,strlen($key)+1);return '';}
$out=arg($argv,'--output-file');if($out===''||!str_starts_with($out,DIRECTORY_SEPARATOR)&&!preg_match('/^[A-Za-z]:[\\\\\/]/',$out)){fwrite(STDERR,"invalid output path\n");exit(2);} $root=dirname(__DIR__,3);$configFile=$root.DIRECTORY_SEPARATOR.'config.php';if(!is_file($configFile)){fwrite(STDERR,"config missing\n");exit(2);} $config=require $configFile;$core=sokna_local_bootstrap($config);$admin=$core->identityRepository()->findActiveById((int)$core->database()->query("SELECT id FROM users WHERE role='admin' AND active=1 ORDER BY id LIMIT 1")->fetchColumn());if(!$admin){fwrite(STDERR,"active admin missing\n");exit(2);} $agent=$core->printing()->createAgent('SOKNA Local Print Worker',$admin);$payload=['server_base_url'=>'https://127.0.0.1','token'=>$agent['token'],'agent_name'=>'SOKNA Local Print Worker'];$dir=dirname($out);if(!is_dir($dir))mkdir($dir,0700,true);file_put_contents($out,json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),LOCK_EX);@chmod($out,0600);echo "provision ready\n";
